{
  "template": "trigger"
}

namespace battery;
table Settings {
  seed:ulong; days:ulong; capacity_kwh:double; power_kw:double; round_trip_efficiency:double;
  export_ratio:double; soc_step_kwh:double;
}
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 7
    },
    {
      "name": "days",
      "type": "uint64",
      "data": 7
    },
    {
      "name": "capacity_kwh",
      "type": "double",
      "data": 10.0
    },
    {
      "name": "power_kw",
      "type": "double",
      "data": 3.0
    },
    {
      "name": "round_trip_efficiency",
      "type": "double",
      "data": 0.9
    },
    {
      "name": "export_ratio",
      "type": "double",
      "data": 0.5
    },
    {
      "name": "soc_step_kwh",
      "type": "double",
      "data": 0.1
    }
  ]
}

namespace battery;
table Scenario {
  seed:ulong; days:ulong; capacity_kwh:double; power_kw:double; round_trip_efficiency:double;
  export_ratio:double; soc_step_kwh:double;
  load:[double]; solar:[double]; flat:[double]; tou:[double]; spot:[double];
}
table Outputs { scenario:Scenario (required); }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "schedule",
        "capacities",
        "tariffs",
        "check"
      ]
    }
  ]
}

namespace battery;
table Outputs { }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "scenario"
    }
  ],
  "params": [
    {
      "name": "tariff",
      "type": "string",
      "data": "spot"
    }
  ]
}

namespace battery;
table Outputs { }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

